const player={pos:new THREE.Vector3(0,0,31),yaw:Math.PI,pitch:0,health:100,armor:50,ammo:30,reserve:120,kills:0,alive:true,speed:8};
let bots=[],running=false,paused=false,viewThird=false,remaining=240,last=performance.now(),shotClock=0,reloading=false,reloadEnd=0,recoil=0,damageFlash=0,toastTimer=0,gameStarted=false;
const keys={},raycaster=new THREE.Raycaster();raycaster.far=85;const center=new THREE.Vector2(0,0);
const playerBody=new THREE.Group();scene.add(playerBody);
const bodyMat=new THREE.MeshStandardMaterial({color:0x536866,roughness:.7}),helmetMat=new THREE.MeshStandardMaterial({color:0x25383a,roughness:.55}),skinMat=new THREE.MeshStandardMaterial({color:0x9a8b72,roughness:.9});
function makeOperator(color=0xff744e){const g=new THREE.Group();const armor=new THREE.MeshStandardMaterial({color,roughness:.72}),darkmat=new THREE.MeshStandardMaterial({color:0x202c2e,roughness:.72});
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.55,4,8),armor);torso.position.y=1.15;torso.castShadow=true;g.add(torso);
 const vest=new THREE.Mesh(new THREE.BoxGeometry(.61,.5,.4),darkmat);vest.position.set(0,1.22,-.02);vest.castShadow=true;g.add(vest);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.23,12,10),skinMat);head.position.y=1.95;head.castShadow=true;g.add(head);
 const helmet=new THREE.Mesh(new THREE.SphereGeometry(.255,12,8,0,Math.PI*2,0,Math.PI*.56),darkmat);helmet.position.y=2.04;helmet.castShadow=true;g.add(helmet);
 const legs=[];for(let s of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.46,3,7),darkmat);leg.position.set(s*.19,.46,0);leg.castShadow=true;g.add(leg);legs.push(leg);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.38,3,7),armor);arm.position.set(s*.42,1.26,-.04);arm.rotation.z=s*.2;arm.castShadow=true;g.add(arm)}
 const gun=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.65),mats.metal);gun.position.set(0,1.18,-.46);g.add(gun);
 g.traverse(o=>{if(o.isMesh)o.userData.enemy=true});g.userData.legs=legs;return g}
const gunView=new THREE.Group();
function addGunPart(parent,geo,mat,pos,rot){let m=new THREE.Mesh(geo,mat);m.position.set(...pos);if(rot)m.rotation.set(...rot);parent.add(m);return m}
addGunPart(gunView,new THREE.BoxGeometry(.17,.18,.72),mats.dark,[0,0,0]);addGunPart(gunView,new THREE.BoxGeometry(.1,.1,.48),mats.metal,[0,.02,-.52]);addGunPart(gunView,new THREE.CylinderGeometry(.035,.035,.52,8),mats.metal,[0,.015,-.92],[Math.PI/2,0,0]);addGunPart(gunView,new THREE.BoxGeometry(.14,.22,.2),mats.metal,[0,-.17,.13],[.2,0,0]);addGunPart(gunView,new THREE.BoxGeometry(.12,.24,.14),mats.dark,[0,-.13,-.26],[.18,0,0]);addGunPart(gunView,new THREE.BoxGeometry(.23,.055,.14),mats.accent,[0,.12,-.15]);addGunPart(gunView,new THREE.BoxGeometry(.11,.12,.16),mats.dark,[0,.13,-.52]);
const flash=new THREE.Mesh(new THREE.SphereGeometry(.13,8,8),new THREE.MeshBasicMaterial({color:0xffe6a3,transparent:true,opacity:.9}));flash.position.set(0,.01,-1.2);flash.visible=false;gunView.add(flash);camera.add(gunView);scene.add(camera);
function spawnBots(){bots.forEach(b=>scene.remove(b.group));bots=[];for(let i=0;i<5;i++){const group=makeOperator([0xff744e,0xe9a34b,0xd66c58,0xb85c50,0xdd8851][i]);const a=i/5*Math.PI*2+.4,r=22+Math.random()*8;group.position.set(Math.sin(a)*r,0,Math.cos(a)*r);scene.add(group);bots.push({group,health:100,alive:true,respawn:0,shoot:1+Math.random()*2,phase:Math.random()*6,legTime:0,hitMeshes:[]});group.traverse(o=>{if(o.isMesh){o.userData.bot=bots[bots.length-1];o.userData.enemy=true}})}}
function resetGame(){player.pos.set(0,0,31);player.yaw=Math.PI;player.pitch=0;player.health=100;player.armor=50;player.ammo=30;player.reserve=120;player.kills=0;player.alive=true;remaining=240;reloading=false;viewThird=false;paused=false;running=true;gameStarted=true;spawnBots();$('#endCard').classList.remove('show');$('#menu').classList.add('hidden');$('#hud').classList.add('active');$('#viewBtn').innerHTML='VIEW &nbsp; FPP';updateHud();requestLock()}
function requestLock(){if(innerWidth>700&&renderer.domElement.requestPointerLock)renderer.domElement.requestPointerLock()}
function showEnd(title,eyebrow,copy){running=false;paused=true;document.exitPointerLock?.();$('#endTitle').innerHTML=title;$('#endEyebrow').textContent=eyebrow;$('#endCopy').textContent=copy;$('#again').querySelector('span').textContent='DEPLOY AGAIN';$('#endCard').classList.add('show')}
function pauseGame(){if(!gameStarted)return;paused=!paused;if(paused){document.exitPointerLock?.();$('#endTitle').innerHTML='COMBAT<br>PAUSED';$('#endEyebrow').textContent='SIMULATION ON HOLD';$('#endCopy').textContent='Take a breath, operator. The field will be waiting.';$('#again').querySelector('span').textContent='RESUME MISSION';$('#endCard').classList.add('show')}else{$('#endCard').classList.remove('show');running=true;requestLock()}}
function setView(){viewThird=!viewThird;$('#viewBtn').innerHTML='VIEW &nbsp; '+(viewThird?'TPP':'FPP');gunView.visible=!viewThird}
$('#play').addEventListener('click',resetGame);$('#again').addEventListener('click',()=>{if(player.alive&&gameStarted&&paused&&remaining>0&&player.kills<15){paused=false;running=true;$('#endCard').classList.remove('show');requestLock()}else resetGame()});$('#pauseBtn').addEventListener('click',pauseGame);$('#viewBtn').addEventListener('click',setView);$('#touchView').addEventListener('click',setView);
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==renderer.domElement&&running&&innerWidth>700&&!paused&&gameStarted){/* Esc leaves the match live; click the canvas to aim again. */}});
renderer.domElement.addEventListener('click',()=>{if(running&&!paused&&innerWidth>700&&document.pointerLockElement!==renderer.domElement)requestLock()});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='KeyV')setView();if(e.code==='Escape'&&gameStarted&&running)pauseGame()});window.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&running){player.yaw-=e.movementX*.0022;player.pitch-=e.movementY*.0019;player.pitch=THREE.MathUtils.clamp(player.pitch,-1.25,1.25)}});
let touchLookId=null,touchX=0,touchY=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&running){touchLookId=e.pointerId;touchX=e.clientX;touchY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&e.pointerId===touchLookId){player.yaw-=(e.clientX-touchX)*.006;player.pitch=THREE.MathUtils.clamp(player.pitch-(e.clientY-touchY)*.005,-1.2,1.2);touchX=e.clientX;touchY=e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerId===touchLookId)touchLookId=null});
function collides(x,z,r=.48){if(Math.abs(x)>37.7||Math.abs(z)>37.7)return true;for(const o of obstacles){let dx=x-o.x,dz=z-o.z;if(Math.abs(dx)<o.rx+r&&Math.abs(dz)<o.rz+r)return true}return false}
function moveEntity(obj,dx,dz,r=.45){let x=obj.position.x+dx,z=obj.position.z;if(!collides(x,obj.position.z,r))obj.position.x=x;x=obj.position.x;z=obj.position.z+dz;if(!collides(x,z,r))obj.position.z=z}
function reload(){if(!running||reloading||player.ammo===30||player.reserve<=0)return;reloading=true;reloadEnd=performance.now()+1450;$('#reloadText').textContent='RELOADING';}
function shoot(){if(!running||paused||!player.alive||reloading)return;if(player.ammo<=0){reload();return}if(performance.now()-shotClock<115)return;shotClock=performance.now();player.ammo--;recoil=Math.min(recoil+.04,.13);flash.visible=true;setTimeout(()=>flash.visible=false,48);updateHud();
 camera.updateMatrixWorld();raycaster.setFromCamera(center,camera);const targets=[];for(const b of bots)if(b.alive)b.group.traverse(o=>{if(o.isMesh)targets.push(o)});const hits=raycaster.intersectObjects(targets,false);let hit=false;if(hits.length){const h=hits[0],bot=h.object.userData.bot;if(bot&&bot.alive){bot.health-=h.point.y>1.72?55:36;hit=true;$('#hitmarker').classList.add('on');setTimeout(()=>$('#hitmarker').classList.remove('on'),110);if(bot.health<=0)eliminate(bot)}}if(!hit){/* visible impact sparks omitted beyond arena */}if(player.ammo===0)reload()}
function eliminate(bot){bot.alive=false;bot.group.visible=false;bot.respawn=4.2;player.kills++;$('#kills').textContent=String(player.kills).padStart(2,'0');$('#toast').textContent='HOSTILE DOWN';$('#toast').classList.add('show');toastTimer=1.3;addFeed('YOU','HOSTILE');updateHud();if(player.kills>=15)showEnd('FIELD<br>MASTER','OBJECTIVE COMPLETE','You cleared the outpost with '+player.kills+' confirmed eliminations. Excellent work, operator.')}
function addFeed(a,b){const el=document.createElement('div');el.className='feed-item';el.innerHTML='<b>'+a+'</b> <span>✕ '+b+'</span>';$('#feed').prepend(el);while($('#feed').children.length>4)$('#feed').lastChild.remove();setTimeout(()=>el.remove(),4800)}
function damage(amount){if(!player.alive||!running)return;let absorb=Math.min(player.armor,amount*.65);player.armor-=absorb;player.health-=amount-absorb;damageFlash=Math.min(1,damageFlash+.7);if(player.health<=0){player.health=0;player.alive=false;$('#toast').textContent='OPERATOR DOWN';$('#toast').classList.add('show');setTimeout(()=>{if(player.kills<15&&remaining>0){player.alive=true;player.health=100;player.armor=35;player.pos.set((Math.random()-.5)*20,0,30);updateHud();$('#toast').classList.remove('show')}} ,2200)}updateHud()}
function updateHud(){ $('#healthNum').textContent=Math.ceil(player.health);$('#armorNum').textContent=Math.ceil(player.armor);$('#healthBar').style.width=Math.max(0,player.health)+'%';$('#armorBar').style.width=Math.max(0,player.armor*2)+'%';$('#ammoNow').textContent=player.ammo;$('#ammoReserve').textContent=player.reserve }
$('#touchFire').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});$('#touchReload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
const stick=$('#stick'),knob=$('#knob');let stickId=null,stickVec={x:0,y:0};stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});function stickMove(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.min(38,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);stickVec={x:Math.cos(a)*len/38,y:Math.sin(a)*len/38};knob.style.transform=`translate(${stickVec.x*30}px,${stickVec.y*30}px)`}stick.addEventListener('pointerup',e=>{stickId=null;stickVec={x:0,y:0};knob.style.transform=''});

